mapper.sql:
SELECT candidate.studentId, MAX(candidate.representativeId) AS sortId FROM ( SELECT e.service_id AS serviceId, e.student_id AS studentId, s.grade_id AS gradeId, COALESCE( MAX(CASE WHEN e.session_id IS NOT NULL THEN e.id ELSE NULL END), MAX(e.id) ) AS representativeId FROM t_as_enrollment e INNER JOIN t_as_student s ON s.id = e.student_id AND s.is_valid = 1 AND s.register_status = 1 AND s.term_id = #{termId} INNER JOIN t_as_service srv ON srv.id = e.service_id AND srv.is_valid = 1 AND srv.term_id = #{termId} WHERE e.is_valid = 1 AND e.school_id = #{schoolId} AND e.service_id IN
#{serviceId}
AND ( (e.enroll_status = 4 AND e.session_id IS NULL AND (e.invite_id IS NULL OR e.enroll_source != 2)) OR (e.enroll_status = 3 AND e.enroll_source = 4 AND e.course_class_id IS NULL AND e.session_id IS NULL) OR (e.enroll_status IN (1, 3) AND e.course_class_id IS NOT NULL AND e.session_id IS NOT NULL) )
AND s.grade_id = #{gradeId}
AND s.class_id = #{classId}
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY e.service_id, e.student_id, s.grade_id ) candidate WHERE ( EXISTS ( SELECT 1 FROM t_as_student_destination visible_destination WHERE visible_destination.is_valid = 1 AND visible_destination.school_id = #{schoolId} AND visible_destination.service_id = candidate.serviceId AND visible_destination.student_id = candidate.studentId AND visible_destination.course_class_id IS NULL AND visible_destination.destination_type IN (2, 3, 4) )
OR EXISTS ( SELECT 1 FROM (
SELECT #{slot.serviceId} AS serviceId, #{slot.sessionDate,jdbcType=TIMESTAMP} AS sessionDate, #{slot.weekDay,jdbcType=INTEGER} AS weekDay, #{slot.startMinute} AS startMinute, #{slot.endMinute} AS endMinute, #{slot.gradeScope,jdbcType=VARCHAR} AS gradeScope
) assignable_slot WHERE assignable_slot.serviceId = candidate.serviceId AND (assignable_slot.gradeScope IS NULL OR LOCATE(CONCAT(',', candidate.gradeId, ','), assignable_slot.gradeScope) > 0) AND NOT EXISTS ( SELECT 1 FROM t_as_enrollment occupied_enrollment INNER JOIN t_as_service occupied_service ON occupied_service.id = occupied_enrollment.service_id AND occupied_service.is_valid = 1 AND occupied_service.term_id = #{termId} INNER JOIN t_as_course_session occupied_session ON occupied_session.id = occupied_enrollment.session_id AND occupied_session.is_valid = 1 AND occupied_session.session_status != 3 WHERE occupied_enrollment.is_valid = 1 AND occupied_enrollment.school_id = #{schoolId} AND occupied_enrollment.student_id = candidate.studentId AND occupied_enrollment.enroll_status IN (1, 3) AND occupied_enrollment.course_class_id IS NOT NULL AND occupied_enrollment.session_id IS NOT NULL AND ( (assignable_slot.sessionDate IS NOT NULL AND occupied_session.session_date IS NOT NULL AND DATE(occupied_session.session_date) = DATE(assignable_slot.sessionDate) AND FLOOR(TIME_TO_SEC(occupied_session.start_time) / 60) = assignable_slot.startMinute AND FLOOR(TIME_TO_SEC(occupied_session.end_time) / 60) = assignable_slot.endMinute) OR (assignable_slot.sessionDate IS NULL AND occupied_session.session_date IS NULL AND occupied_session.week_day = assignable_slot.weekDay AND FLOOR(TIME_TO_SEC(occupied_session.start_time) / 60) = assignable_slot.startMinute AND FLOOR(TIME_TO_SEC(occupied_session.end_time) / 60) = assignable_slot.endMinute) ) ) AND NOT EXISTS ( SELECT 1 FROM t_as_student_destination occupied_destination INNER JOIN t_as_service destination_service ON destination_service.id = occupied_destination.service_id AND destination_service.is_valid = 1 AND destination_service.term_id = #{termId} INNER JOIN t_as_course_session destination_session ON destination_session.id = occupied_destination.session_id AND destination_session.is_valid = 1 AND destination_session.session_status != 3 WHERE occupied_destination.is_valid = 1 AND occupied_destination.school_id = #{schoolId} AND occupied_destination.student_id = candidate.studentId AND occupied_destination.course_class_id IS NULL AND occupied_destination.session_id IS NOT NULL AND occupied_destination.destination_type IN (2, 3, 4) AND ( (assignable_slot.sessionDate IS NOT NULL AND destination_session.session_date IS NOT NULL AND DATE(destination_session.session_date) = DATE(assignable_slot.sessionDate) AND FLOOR(TIME_TO_SEC(destination_session.start_time) / 60) = assignable_slot.startMinute AND FLOOR(TIME_TO_SEC(destination_session.end_time) / 60) = assignable_slot.endMinute) OR (assignable_slot.sessionDate IS NULL AND destination_session.session_date IS NULL AND destination_session.week_day = assignable_slot.weekDay AND FLOOR(TIME_TO_SEC(destination_session.start_time) / 60) = assignable_slot.startMinute AND FLOOR(TIME_TO_SEC(destination_session.end_time) / 60) = assignable_slot.endMinute) ) ) LIMIT 1 )
) GROUP BY candidate.studentId

mapper.select:
SELECT SQL_CALC_FOUND_ROWS candidate_page.studentId
FROM (

) candidate_page
ORDER BY candidate_page.sortId DESC, candidate_page.studentId DESC
LIMIT #{offset}, #{limit}

SELECT DISTINCT t.id AS termId, t.term_name AS termName, cc.id AS courseClassId, cc.course_class_name AS courseClassName, cs.week_day AS weekDay, DATE_FORMAT(cs.start_time, '%H:%i') AS startTime, DATE_FORMAT(cs.end_time, '%H:%i') AS endTime, cc.place_id AS placeId, cat.category_name AS categoryName, cc.enroll_type AS enrollType, e.enroll_time studentEnrollTime, e.student_id studentId, srv.course_start_date classStartTime, srv.course_end_date classEndTime FROM t_as_enrollment e INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service srv ON e.service_id = srv.id AND srv.is_valid = 1 LEFT JOIN t_educl_term t ON srv.term_id = t.id AND t.is_valid = 1 LEFT JOIN t_as_course_session cs ON cs.course_class_id = cc.id AND cs.is_valid = 1 AND cs.session_status != 3 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_status = 1 AND e.student_id in
#{item}
AND e.school_id = #{schoolId}
AND srv.term_id = #{termId}
ORDER BY t.id ASC, cc.id ASC, cs.week_day ASC, cs.start_time ASC

SELECT COUNT(DISTINCT CASE WHEN ( (e.enroll_status = 1 AND e.enroll_source IN (1, 2)) OR (e.enroll_status = 3 AND e.enroll_source = 3) ) AND e.course_class_id IS NOT NULL AND e.session_id IS NOT NULL THEN CONCAT(e.student_id, ':', COALESCE(srv.term_id, 0), ':', e.course_class_id) END) AS registeredCount, COUNT(DISTINCT CASE WHEN e.enroll_status = 3 AND e.enroll_source = 4 AND ( (e.course_class_id IS NOT NULL AND e.session_id IS NOT NULL) OR (ncd.id IS NOT NULL) ) THEN CONCAT(e.student_id, ':', COALESCE(srv.term_id, 0), ':', CASE WHEN e.course_class_id IS NOT NULL THEN CAST(e.course_class_id AS CHAR) ELSE CONCAT('U:', e.service_id) END) END) AS assignedCount FROM t_as_enrollment e INNER JOIN t_as_service srv ON e.service_id = srv.id AND srv.is_valid = 1 LEFT JOIN t_as_student_destination ncd ON ncd.is_valid = 1 AND ncd.school_id = e.school_id AND ncd.service_id = e.service_id AND ncd.student_id = e.student_id AND ncd.course_class_id IS NULL AND ncd.destination_type IN (2, 3, 4) WHERE e.is_valid = 1
AND e.school_id = #{schoolId}
AND e.student_id IN
#{sid}
AND e.service_id IN
#{sid}
AND srv.term_id = #{termId}

SELECT e.id AS enrollmentId, e.school_id AS schoolId, e.service_id AS serviceId, e.student_id AS studentId, e.student_no AS studentNo, e.enroll_status AS enrollStatus, e.invite_id AS inviteId, e.enroll_time AS enrollTime, s.student_name AS studentName, s.grade_id AS gradeId, s.class_id AS classId, s.register_status AS registerStatus, s.term_id AS studentTermId, srv.term_id AS serviceTermId FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 INNER JOIN t_as_service srv ON e.service_id = srv.id AND srv.is_valid = 1 WHERE e.is_valid = 1 AND e.course_class_id IS NULL AND e.session_id IS NULL
AND e.school_id = #{schoolId}
AND e.service_id IN
#{sid}
AND s.grade_id = #{gradeId}
AND s.class_id = #{classId}
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.id DESC

SELECT DISTINCT student_id
FROM t_as_enrollment
WHERE is_valid = 1
  AND school_id = #{schoolId}
  AND service_id = #{serviceId}
  AND student_id IN

    #{studentId}

SELECT s.id, s.school_id, s.term_id, s.student_no
FROM t_as_student s
WHERE s.is_valid = 1
  AND s.school_id = #{schoolId}
  AND s.term_id = #{termId}
  AND s.register_status = 1
  AND s.class_id IN

    #{scopeClassId}


    AND s.grade_id = #{gradeId}


    AND s.class_id = #{classId}


    AND (LOCATE(CAST(#{keyword} AS BINARY), CAST(s.student_no AS BINARY)) > 0
         OR LOCATE(CAST(#{keyword} AS BINARY), CAST(s.student_name AS BINARY)) > 0)

  AND NOT EXISTS (
      SELECT 1
      FROM t_as_enrollment e
      WHERE e.is_valid = 1
        AND e.school_id = #{schoolId}
        AND e.service_id = #{serviceId}
        AND e.student_id = s.id
  )
ORDER BY s.id ASC
LIMIT #{limit}

SELECT DISTINCT occupied.schoolId, occupied.termId, occupied.studentId, occupied.sessionId, occupied.sessionDate, occupied.weekDay, occupied.startTime, occupied.endTime FROM ( SELECT e.school_id AS schoolId, srv.term_id AS termId, e.student_id AS studentId, CASE WHEN cs.session_date IS NULL AND (cs.week_day IS NULL OR cs.start_time IS NULL OR cs.end_time IS NULL) THEN cs.id ELSE NULL END AS sessionId, cs.session_date AS sessionDate, cs.week_day AS weekDay, cs.start_time AS startTime, cs.end_time AS endTime FROM t_as_enrollment e INNER JOIN t_as_service srv ON srv.id = e.service_id AND srv.is_valid = 1 INNER JOIN t_as_course_session cs ON cs.id = e.session_id AND cs.is_valid = 1 AND cs.session_status != 3 WHERE e.is_valid = 1 AND e.enroll_status IN (1, 3) AND e.course_class_id IS NOT NULL AND e.session_id IS NOT NULL AND e.school_id IN
#{schoolId}
AND srv.term_id IN
#{termId}
AND e.student_id IN
#{studentId}
UNION ALL
SELECT d.school_id AS schoolId, srv.term_id AS termId, d.student_id AS studentId, CASE WHEN cs.session_date IS NULL AND (cs.week_day IS NULL OR cs.start_time IS NULL OR cs.end_time IS NULL) THEN cs.id ELSE NULL END AS sessionId, cs.session_date AS sessionDate, cs.week_day AS weekDay, cs.start_time AS startTime, cs.end_time AS endTime FROM t_as_student_destination d INNER JOIN t_as_service srv ON srv.id = d.service_id AND srv.is_valid = 1 INNER JOIN t_as_course_session cs ON cs.id = d.session_id AND cs.is_valid = 1 AND cs.session_status != 3 WHERE d.is_valid = 1 AND d.course_class_id IS NULL AND d.session_id IS NOT NULL AND d.destination_type IN (2, 3, 4) AND d.school_id IN
#{schoolId}
AND srv.term_id IN
#{termId}
AND d.student_id IN
#{studentId}
) occupied

mapper.sql:
SELECT e.id AS enrollmentId, e.school_id AS schoolId, e.service_id AS serviceId, e.course_class_id AS courseClassId, e.session_id AS sessionId, e.student_id AS studentId, e.student_no AS studentNo, e.enroll_source AS enrollSource, e.enroll_status AS enrollStatus, e.operator_type AS operatorType, e.operator_user_id AS operatorUserId, e.operator_name AS operatorName, e.enroll_time AS enrollTime, s.student_name AS studentName, s.gender AS gender, s.grade_id AS gradeId, s.class_id AS classId, s.register_status AS registerStatus, s.term_id AS studentTermId, s.student_identity_id AS studentIdentityId, srv.service_name AS serviceName, srv.term_id AS serviceTermId, cc.course_class_name AS courseClassName, cc.category_id AS categoryId, cc.enroll_type AS enrollType, cc.capacity AS capacity, cat.category_name AS categoryName, t.term_name AS termName, g.grade_name AS gradeName, cl.class_name AS className, IFNULL(lc.learnedSessions, 0) AS learnedSessions FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 INNER JOIN t_as_service srv ON e.service_id = srv.id AND srv.is_valid = 1 LEFT JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 LEFT JOIN t_educl_term t ON srv.term_id = t.id AND t.is_valid = 1 LEFT JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 LEFT JOIN t_educl_class cl ON s.class_id = cl.id AND cl.is_valid = 1 LEFT JOIN ( SELECT a.student_id, cs.course_class_id, COUNT(DISTINCT a.session_id) AS learnedSessions FROM t_as_attendance_record a INNER JOIN t_as_course_session cs ON a.session_id = cs.id AND cs.is_valid = 1 WHERE a.is_valid = 1 AND a.target_type = 1 AND a.attendance_status IN (1, 2, 3) AND cs.session_status != 3 GROUP BY a.student_id, cs.course_class_id ) lc ON lc.student_id = e.student_id AND lc.course_class_id = e.course_class_id WHERE e.is_valid = 1 AND e.course_class_id IS NOT NULL AND e.session_id IS NOT NULL AND e.enroll_status IN (1, 3) AND s.register_status IN (0, 1) AND s.term_id = srv.term_id
AND e.school_id = #{schoolId}
AND e.service_id IN
#{sid}
AND s.grade_id = #{gradeId}
AND s.class_id = #{classId}
AND cc.enroll_type = #{enrollType}
AND (s.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT SQL_CALC_FOUND_ROWS base.* FROM (
) base INNER JOIN ( SELECT MAX(e2.id) AS maxId FROM t_as_enrollment e2 INNER JOIN t_as_student s2 ON e2.student_id = s2.id AND s2.is_valid = 1 INNER JOIN t_as_service srv2 ON e2.service_id = srv2.id AND srv2.is_valid = 1 LEFT JOIN t_as_course_class cc2 ON e2.course_class_id = cc2.id AND cc2.is_valid = 1 WHERE e2.is_valid = 1 AND e2.course_class_id IS NOT NULL AND e2.session_id IS NOT NULL AND e2.enroll_status IN (1, 3) AND s2.register_status IN (0, 1) AND s2.term_id = srv2.term_id
AND e2.school_id = #{schoolId}
AND e2.service_id IN
#{sid}
AND s2.grade_id = #{gradeId}
AND s2.class_id = #{classId}
AND cc2.enroll_type = #{enrollType}
AND (s2.student_no LIKE CONCAT('%', #{keyword}, '%') OR s2.student_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY s2.id, e2.service_id, e2.course_class_id ) grp ON base.enrollmentId = grp.maxId ORDER BY base.enrollmentId DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ( SELECT MAX(e2.id) AS maxId FROM t_as_enrollment e2 INNER JOIN t_as_student s2 ON e2.student_id = s2.id AND s2.is_valid = 1 INNER JOIN t_as_service srv2 ON e2.service_id = srv2.id AND srv2.is_valid = 1 LEFT JOIN t_as_course_class cc2 ON e2.course_class_id = cc2.id AND cc2.is_valid = 1 WHERE e2.is_valid = 1 AND e2.course_class_id IS NOT NULL AND e2.session_id IS NOT NULL AND e2.enroll_status IN (1, 3) AND s2.register_status IN (0, 1) AND s2.term_id = srv2.term_id
AND e2.school_id = #{schoolId}
AND e2.service_id IN
#{sid}
AND s2.grade_id = #{gradeId}
AND s2.class_id = #{classId}
AND cc2.enroll_type = #{enrollType}
AND (s2.student_no LIKE CONCAT('%', #{keyword}, '%') OR s2.student_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY s2.id, e2.service_id, e2.course_class_id ) grouped

SELECT MIN(e.id) AS id, e.school_id, e.student_id, e.course_class_id, MAX(e.enroll_status) AS enroll_status FROM t_as_enrollment e INNER JOIN t_as_course_session cs ON cs.id = e.session_id AND cs.is_valid = 1 AND cs.session_status != 3 INNER JOIN t_as_course_class cc ON cc.id = e.course_class_id AND cc.is_valid = 1 WHERE e.is_valid = 1 AND e.school_id = #{schoolId} AND e.student_id IN
#{studentId}
AND e.session_id IS NOT NULL AND e.course_class_id IS NOT NULL AND e.enroll_status IN (0, 1, 3) GROUP BY e.school_id, e.student_id, e.course_class_id

SELECT e.id, e.school_id, e.student_id, e.course_class_id, e.enroll_status, e.invite_id, e.update_time FROM t_as_enrollment e WHERE e.is_valid = 1 AND e.student_id IN
#{studentId}
AND e.session_id IS NOT NULL
AND e.school_id IN
#{schoolId}
AND NOT EXISTS ( SELECT 1 FROM t_as_enrollment newer WHERE newer.is_valid = 1 AND newer.school_id = e.school_id AND newer.student_id = e.student_id AND newer.session_id IS NOT NULL AND ( (newer.update_time IS NOT NULL AND e.update_time IS NULL) OR newer.update_time > e.update_time OR ( (newer.update_time = e.update_time OR (newer.update_time IS NULL AND e.update_time IS NULL)) AND newer.id > e.id ) ) )
